{"code":"import random

def generate(rng):
    n = rng.choice([15,17,19,21,23])
    # checkerboard-like background, with odd/even row phases and colors
    a,b,c = rng.choice([(3,2,1),(4,6,5),(8,7,9),(2,4,1)])
    grid=[]
    for r in range(n):
        row=[]
        for c0 in range(n):
            if r%2==0: row.append(a if c0%2==0 else b)
            else: row.append(b if c0%2==0 else c)
        grid.append(row)
    # erase several axis-aligned rectangular patches, usually aligned to cells
    for _ in range(rng.randint(1,5)):
        r1=rng.randrange(n); r2=rng.randrange(r1,n)
        c1=rng.randrange(n); c2=rng.randrange(c1,n)
        # favor patches of at least 2x2, and preserve occasional boundary strips naturally
        if r2-r1<1: r2=min(n-1,r1+1)
        if c2-c1<1: c2=min(n-1,c1+1)
        for r in range(r1,r2+1):
            for c0 in range(c1,c2+1): grid[r][c0]=0
    return grid"}

